/* 第06轮：候选媒体只读，剪辑使用实例、审阅依赖和交付冻结独立保存。 */
window.createCimoraEditModel=function(M,S){
 const clone=M.clone,kinds=['picture','continuity','subtitle','sound'],labels={picture:'画面与角色',continuity:'画面接续',subtitle:'字幕与对白归属',sound:'声音设定'},resumed=new WeakSet();
 const shots=c=>M.production.shots(c.e),shot=(c,id)=>[...shots(c),...(c.e.archivedShots||[])].find(s=>s.id===id);
 function candidate(c,x){return shot(c,x.shotId)?.candidates.find(v=>v.id===x.candidateId);}
 function media(v){if(!v?.media||v.status!=='ready')return null;const m=v.media;return {url:m.playbackUrl||m.url,offset:m.playbackUrl?0:Number(m.in)||0,duration:Number(m.out)-Number(m.in)};}
 function clip(c,s,v){const length=media(v).duration;return {id:S.id('use'),shotId:s.id,candidateId:v.id,in:0,out:length,subtitle:{enabled:!!s.dialogue,text:s.dialogue||'',speaker:'未指定',start:0,end:length},audio:{muted:false,volume:80},voice:{enabled:false,text:'',speaker:'未指定',volume:70},checks:{}};}
 function ensure(c){if(!c.e.editing){c.e.editing={version:1,revision:1,clips:shots(c).flatMap(s=>{const a=s.candidates.find(v=>v.id===s.adoptedId);return media(a)?[clip(c,s,a)]:[];}),selectedId:null,music:{enabled:false,name:'项目配乐意图',volume:30},deliveries:[],preview:{index:0,time:0,playing:false}};c.e.editing.selectedId=c.e.editing.clips[0]?.id||null;M.save();}const e=c.e.editing;if(!resumed.has(e)){e.preview.playing=false;resumed.add(e);}return e;}
 function rows(c){let start=0;return ensure(c).clips.map((x,index)=>{const s=shot(c,x.shotId),a=candidate(c,x),m=media(a),duration=x.out-x.in,row={...x,index,s,a,media:m,duration,start,end:start+duration};start=row.end;return row;});}
 const selected=(c,id)=>ensure(c).clips.find(x=>x.id===id);
 function changed(c){ensure(c).revision++;M.save();}
 function add(c,shotId,candidateId){const s=shot(c,shotId),a=s?.candidates.find(v=>v.id===candidateId);if(!media(a))return {error:'该候选没有可播放媒体'};const x=clip(c,s,a);ensure(c).clips.push(x);ensure(c).selectedId=x.id;changed(c);return x;}
 function update(c,id,values){const x=selected(c,id);if(!x)return '使用片段不存在';const n={...clone(x),...clone(values)},a=candidate(c,n),m=media(a);if(!m)return '该候选没有可播放媒体';n.in=Number(n.in);n.out=Number(n.out);if(!Number.isFinite(n.in)||!Number.isFinite(n.out)||n.in<0||n.out>m.duration+.001||n.out-n.in<.1)return '使用区间需在媒体时长内，且至少0.1秒';
  for(const k of ['audio','voice']){n[k]={...x[k],...(values[k]||{})};n[k].volume=Math.max(0,Math.min(100,Number(n[k].volume)||0));}
  n.subtitle={...x.subtitle,...(values.subtitle||{})};const len=n.out-n.in;if(!values.subtitle&&(n.in!==x.in||n.out!==x.out)){n.subtitle.start=Math.min(n.subtitle.start,Math.max(0,len-.1));n.subtitle.end=Math.min(n.subtitle.end,len);}
  n.subtitle.start=Number(n.subtitle.start);n.subtitle.end=Number(n.subtitle.end);if(n.subtitle.enabled&&(n.subtitle.start<0||n.subtitle.end>len+.001||n.subtitle.end<=n.subtitle.start))return '字幕显示区间必须在使用片段内';Object.assign(x,n);changed(c);return null;}
 function duplicate(c,id){const x=selected(c,id);if(!x)return {error:'使用片段不存在'};const n={...clone(x),id:S.id('use'),checks:{}};ensure(c).clips.splice(ensure(c).clips.indexOf(x)+1,0,n);ensure(c).selectedId=n.id;changed(c);return n;}
 function move(c,id,delta){const xs=ensure(c).clips,i=xs.findIndex(x=>x.id===id),j=i+delta;if(i<0||j<0||j>=xs.length)return;[xs[i],xs[j]]=[xs[j],xs[i]];changed(c);}
 function remove(c,id){const e=ensure(c);e.clips=e.clips.filter(x=>x.id!==id);if(e.selectedId===id)e.selectedId=e.clips[0]?.id||null;changed(c);}
 function music(c,v){Object.assign(ensure(c).music,v);ensure(c).music.volume=Math.max(0,Math.min(100,Number(ensure(c).music.volume)||0));changed(c);}
 function signatures(c,r){const rs=rows(c),prev=rs[r.index-1],pic=x=>x?[x.id,x.shotId,x.candidateId,x.in,x.out,x.s?.adoptedId]:null;return {picture:JSON.stringify(pic(r)),continuity:JSON.stringify([pic(prev),pic(r)]),subtitle:JSON.stringify([r.subtitle,r.duration]),sound:JSON.stringify([r.audio,r.voice,ensure(c).music,r.duration])};}
 function rule(r,kind){if(!r.media)return '候选缺少可播放文件';if(r.in<0||r.out>r.media.duration+.001||r.duration<.1)return '使用片段超出媒体区间';if(kind==='subtitle'&&r.subtitle.enabled){if(!r.subtitle.text.trim())return '启用字幕但内容为空';if(r.subtitle.text.length>60)return '单条字幕超过60字，请拆短本片段字幕（规则演示）';if(r.subtitle.start<0||r.subtitle.end>r.duration+.001||r.subtitle.end<=r.subtitle.start)return '字幕显示时间超出使用片段';}if(kind==='sound'&&r.voice.enabled&&!r.voice.text.trim())return '独立对白已启用但文案为空';return null;}
 function issues(c){return rows(c).flatMap(r=>kinds.flatMap(kind=>{const error=rule(r,kind),sig=signatures(c,r)[kind],check=r.checks[kind];if(!error&&check?.signature===sig)return [];return [{id:r.id+':'+kind,clipId:r.id,shotId:r.shotId,title:(r.s?.title||'镜头已移除')+' · '+labels[kind],kind,time:r.start+(kind==='subtitle'?r.subtitle.start:0),state:error?'blocked':check?'stale':'pending',basis:error||(kind==='picture'?'人工检查人物、动作及所用候选；未做AI视觉识别':kind==='continuity'?'人工核对前项结尾与本项开头；依据候选、裁切及独立剪辑顺序':kind==='subtitle'?'人工核对当前字幕、说话人与相对显示时间；长度规则仅演示':'人工确认原片音量、独立对白及配乐意图；当前示例无声，未验证混音'),signature:sig}];}));}
 function confirm(c,id,kind){const r=rows(c).find(r=>r.id===id);if(!r||!kinds.includes(kind))return '审阅项不存在';const error=rule(r,kind);if(error)return error;selected(c,id).checks[kind]={signature:signatures(c,r)[kind],at:new Date().toISOString(),mode:'manual'};M.save();return null;}
 function freeze(c){const e=ensure(c);if(!e.clips.length)return {error:'先添加使用片段'};if(issues(c).length)return {error:'请先处理并重新确认当前审阅项'};const delivery=clone({id:S.id('edit-delivery'),createdAt:new Date().toISOString(),kind:'模拟视频交付 / 冻结工程清单',prototype:true,project:{id:c.p.id,name:c.p.name},episode:{id:c.c.id,title:c.c.title},revision:e.revision,orderPolicy:'独立剪辑播放顺序，不改镜头叙事数组或画布位置',duration:rows(c).at(-1).end,clips:rows(c).map(r=>({id:r.id,shotId:r.shotId,title:r.s.title,candidate:clone(r.a),in:r.in,out:r.out,start:r.start,end:r.end,subtitle:r.subtitle,audio:r.audio,voice:r.voice,checks:r.checks})),music:e.music,notice:'无MP4合成；无独立对白/配乐音频，无混音验证；本文件为冻结工程清单。'});e.deliveries.unshift(delivery);M.save();return {delivery};}
 M.editing={ensure,rows,selected,candidate,media,add,update,duplicate,move,remove,music,signatures,issues,confirm,freeze,kinds,labels};return M;
};
